// Parse a JSON 1D integer array line ("[2,7,11,15]") by blanking the brackets
// and commas, then reading the integers with a stringstream.
static vector<long long> parseIntArray(const string& line) {
    string s = line;
    for (char& c : s) {
        if (c == '[' || c == ']' || c == ',') c = ' ';
    }
    stringstream ss(s);
    vector<long long> v;
    long long x;
    while (ss >> x) v.push_back(x);
    return v;
}

int main() {
    // Move bash-supplied fd 3 to a private slot and close fd 3 so user code
    // can't touch it. The dup is what the wrapper uses to deliver the answer.
    int _answer_fd = dup(3);
    close(3);

    // Two stdin lines for this test case: line 0 = nums, line 1 = target.
    string numsLine, targetLine;
    getline(cin, numsLine);
    getline(cin, targetLine);

    vector<long long> nums = parseIntArray(numsLine);
    long long target = stoll(targetLine);

    vector<int> result = solve(nums, target);

    string payload = "[";
    for (size_t i = 0; i < result.size(); ++i) {
        if (i) payload += ',';
        payload += to_string(result[i]);
    }
    payload += ']';
    write(_answer_fd, payload.c_str(), payload.size());
    close(_answer_fd);
    return 0;
}

