// Return the 0-based indices (i, j) with i < j of the two elements of nums
// whose sum equals target. Exactly one valid answer exists.
vector<int> solve(vector<long long> nums, long long target) {
    unordered_map<long long, int> seen;
    for (int i = 0; i < (int)nums.size(); ++i) {
        auto it = seen.find(target - nums[i]);
        if (it != seen.end()) return {it->second, i};
        seen[nums[i]] = i;
    }
    return {};
}

// Return the 0-based indices (i, j) with i < j of the two elements of nums
// whose sum equals target. Exactly one valid answer exists.
func solve(nums []int64, target int64) []int {
	seen := make(map[int64]int)
	for i, x := range nums {
		if j, ok := seen[target-x]; ok {
			return []int{j, i}
		}
		seen[x] = i
	}
	return nil
}
